{
  "findings": [
    {
      "check_id": "CKV_AWS_40",
      "title": "Ensure IAM policies are attached only to groups or roles",
      "resource": "aws_iam_user_policy_attachment.privesc3-passrole-user-attach-policy",
      "severity": "MEDIUM",
      "explanation": "Attaching IAM policies directly to users can lead to excessive privileges and increased management complexity."
    },
    {
      "check_id": "UNKNOWN",
      "title": "IAM policy with wildcard ARN",
      "resource": "aws_iam_policy.fn1-passrole-star",
      "severity": "HIGH",
      "explanation": "The policy ARN 'aws_iam_policy.fn1-passrole-star.arn' suggests a wildcard policy that may grant excessive permissions."
    }
  ],
  "patched_code": "resource \"aws_iam_group\" \"privesc3-group\" {\n  name = \"privesc3-group\"\n}\n\nresource \"aws_iam_user_group_membership\" \"privesc3-user-group-membership\" {\n  user = aws_iam_user.fn1-privesc3-partial-user.name\n  groups = [aws_iam_group.privesc3-group.name]\n}\n\nresource \"aws_iam_group_policy_attachment\" \"privesc3-group-attach-policy\" {\n  group      = aws_iam_group.privesc3-group.name\n  policy_arn = aws_iam_policy.fn1-passrole-star.arn\n}",
  "fix_summary": "Replaced direct user policy attachment with group policy attachment to reduce access management complexity and potential for excessive privileges."
}
